// 同目录临时文件 + rename，避免半成品证明文件留在输出目录。
async function atomicWrite(target, contents) {
  const dir = dirname(target);
  const tmp = join(dir, `.${basename(target)}.${process.pid}.tmp`);
  await writeFile(tmp, contents, { mode: 0o644 });
  try {
    await import('node:fs/promises').then((fs) => fs.rename(tmp, target));
  } catch (err) {
    try {
      await import('node:fs/promises').then((fs) => fs.rm(tmp, { force: true }));
    } catch {
      /* 忽略清理失败 */
    }
    throw err;
  }
}

