async function fileTypeFromPath(fullPath, data) {
  // 极简魔数嗅探，仅用于清单的 type 字段；不识别时回退为扩展名或 "data"。
  const sniff = (sig) => data.subarray(0, sig.length).equals(Buffer.from(sig));
  if (sniff([0x1f, 0x8b])) return 'application/gzip';
  if (sniff('\x50\x4b\x03\x04')) return 'application/zip';
  if (sniff('%PDF-')) return 'application/pdf';
  if (sniff('\x7fELF')) return 'application/x-elf';
  if (sniff('MZ')) return 'application/x-dosexec';
  if (sniff([0xff, 0xd8, 0xff])) return 'image/jpeg';
  if (sniff('\x89PNG\r\n\x1a\n')) return 'image/png';
  // 类脚本/文本：UTF-16 BOM 或不含 NUL 字节则视为 text。
  if (sniff([0xef, 0xbb, 0xbf]) || sniff([0xff, 0xfe]) || sniff([0xfe, 0xff])) return 'text/plain';
  if (!data.subarray(0, 512).includes(0)) return 'text/plain';
  const ext = basename(fullPath).split('.').pop();
  return ext && ext !== basename(fullPath) ? `application/x-${ext.toLowerCase()}` : 'application/octet-stream';
}

