    [proofAbs, '证明文件'],
    [sigAbs, '签名文件'],
    [keyAbs, '公钥'],
  ]) {
    try {
      await access(p, fsConstants.R_OK);
    } catch (err) {
      throw wrapFsError(err, `读取${label}`);
    }
  }

